style.css:
@-moz-document domain("roblox.com") {
/* Fondo general sólido */
    body, html, #app {
        background-color: #0a1a2b !important;  /* azul muy oscuro */
        color: #c0c9d8 !important;
    }

    /* Cabecera, barra superior y menús fijos */
    header, nav, .navbar, .top-nav, .nav-menu {
        background-color: #0a1a2b !important;
        border-bottom: 1px solid #13203b !important;
    }

    /* Paneles y cajas */
    .card, .container, .game-card, .section, .modal, .panel {
        background-color: #0f2a44 !important;
        border-radius: 8px !important;
        border: 1px solid #13203b !important;
        color: #c0c9d8 !important;
    }

    /* Botones */
    button, .btn, .btn-primary {
        background-color: #13203b !important;
        color: #d0d9e8 !important;
        border-radius: 6px !important;
        border: none !important;
        padding: 6px 12px !important;
    }

    button:hover, .btn:hover, .btn-primary:hover {
        background-color: #1a304f !important;
    }

    /* Links */
    a, a:visited {
        color: #5a7fa0 !important;
        text-decoration: none !important;
    }

    a:hover {
        color: #7a9ec1 !important;
        text-decoration: underline !important;
    }

    /* Inputs y cajas de texto */
    input, textarea, select {
        background-color: #13203b !important;
        color: #c0c9d8 !important;
        border: 1px solid #1a304f !important;
        border-radius: 6px !important;
        padding: 6px !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #13203b !important;
        border-radius: 10px;
    }

    ::-webkit-scrollbar-track {
        background-color: #0a1a2b !important;
    }

    /* Menús desplegables y overlays */
    .dropdown-menu, .menu-panel, .modal-backdrop {
        background-color: #0f2a44 !important;
        border: 1px solid #13203b !important;
        border-radius: 6px !important;
    }
}
